changeSet.sql:
ALTER TABLE arrangement_version
  ADD CONSTRAINT ck_arrangement_version_status CHECK (status IN ('UNVERIFIED', 'APPROVED')),
  ADD CONSTRAINT ck_arrangement_version_approval
    CHECK ((status = 'APPROVED') = (approved_by IS NOT NULL AND approved_at IS NOT NULL));
CREATE UNIQUE INDEX uq_arrangement_version_number ON arrangement_version (arrangement_id, version_number) WHERE deleted = FALSE;
CREATE INDEX idx_arrangement_version_arrangement ON arrangement_version (arrangement_id, deleted);
CREATE INDEX idx_arrangement_version_media_asset ON arrangement_version (media_asset_id);

ALTER TABLE score_version DROP CONSTRAINT ck_score_version_origin;
ALTER TABLE score_version
  ADD CONSTRAINT ck_score_version_origin
    CHECK (origin IN ('OMR_AUDIVERIS', 'OMR_HOMR', 'UPLOAD_MUSICXML', 'UPLOAD_MIDI', 'CORRECTION', 'WRITING', 'ARRANGEMENT'));

ALTER TABLE score_version
  ADD CONSTRAINT ck_score_version_arrangement
    CHECK ((origin = 'ARRANGEMENT') = (arrangement_version_id IS NOT NULL));
CREATE INDEX idx_score_version_arrangement_version ON score_version (arrangement_version_id)
  WHERE arrangement_version_id IS NOT NULL;
CREATE UNIQUE INDEX uq_sheet_music_arrangement_row ON sheet_music (track_id, arrangement_row)
  WHERE deleted = FALSE AND arrangement_row IS NOT NULL;

rollback.sql:
DROP INDEX uq_sheet_music_arrangement_row;
DROP INDEX idx_score_version_arrangement_version;
ALTER TABLE score_version DROP CONSTRAINT ck_score_version_arrangement;

ALTER TABLE score_version DROP CONSTRAINT ck_score_version_origin;
ALTER TABLE score_version
  ADD CONSTRAINT ck_score_version_origin
    CHECK (origin IN ('OMR_AUDIVERIS', 'OMR_HOMR', 'UPLOAD_MUSICXML', 'UPLOAD_MIDI', 'CORRECTION', 'WRITING'));

changeSet.sql:
ALTER TABLE score_draft DROP CONSTRAINT ck_score_draft_target_type;
ALTER TABLE score_draft
  ADD CONSTRAINT ck_score_draft_target_type CHECK (target_type IN ('PART', 'ARRANGEMENT')),
  ADD CONSTRAINT ck_score_draft_rows CHECK ((target_type = 'ARRANGEMENT') = (rows_json IS NOT NULL));
ALTER TABLE score_edit_lock DROP CONSTRAINT ck_score_edit_lock_target_type;
ALTER TABLE score_edit_lock
  ADD CONSTRAINT ck_score_edit_lock_target_type CHECK (target_type IN ('PART', 'ARRANGEMENT'));

rollback.sql:
DELETE FROM score_edit_lock WHERE target_type = 'ARRANGEMENT';
DELETE FROM score_draft WHERE target_type = 'ARRANGEMENT';
ALTER TABLE score_edit_lock DROP CONSTRAINT ck_score_edit_lock_target_type;
ALTER TABLE score_edit_lock ADD CONSTRAINT ck_score_edit_lock_target_type CHECK (target_type IN ('PART'));
ALTER TABLE score_draft DROP CONSTRAINT ck_score_draft_rows;
